import{_ as t,o as r,c as a,a3 as i}from"./chunks/framework.DQ-7HQaQ.js";const g=JSON.parse('{"title":"Similar projects","description":"Eight primary-source references for graph retrieval, document enrichment, temporal knowledge, and pipeline design.","frontmatter":{"title":"Similar projects","description":"Eight primary-source references for graph retrieval, document enrichment, temporal knowledge, and pipeline design."},"headers":[],"relativePath":"research/similar-projects.md","filePath":"research/similar-projects.md","lastUpdated":1794433168000}'),o={name:"research/similar-projects.md"};function n(s,e,d,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="similar-projects" tabindex="-1">Similar projects <a class="header-anchor" href="#similar-projects" aria-label="Permalink to &quot;Similar projects&quot;">​</a></h1><p><strong>Sources checked: November 5, 2026.</strong> These projects overlap with parts of our system; they are study references and possible integration candidates. They have not been benchmarked against our Rust streaming service, SQLite retrieval proposal, or document corpus. Project descriptions do not establish equivalent correctness, latency, or operational guarantees.</p><p>Use these references alongside our <a href="/knowledge-lab/architecture/ingestion">ingestion DAG</a>, <a href="/knowledge-lab/architecture/retrieval">retrieval design</a>, and <a href="/knowledge-lab/architecture/contracts">service contracts</a>.</p><h2 id="comparison-at-a-glance" tabindex="-1">Comparison at a glance <a class="header-anchor" href="#comparison-at-a-glance" aria-label="Permalink to &quot;Comparison at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Project and team</th><th>Kind</th><th>Closest overlap</th><th>Best idea to investigate</th></tr></thead><tbody><tr><td><a href="https://github.com/microsoft/graphrag" target="_blank" rel="noreferrer">Microsoft GraphRAG</a></td><td>Research indexing/query implementation</td><td>AI-extracted entities, relationships, and summaries</td><td>Explicit graph artifacts and local versus corpus-wide retrieval</td></tr><tr><td><a href="https://github.com/HKUDS/LightRAG" target="_blank" rel="noreferrer">LightRAG — HKUDS</a></td><td>Graph-RAG framework with an API server</td><td>Graph/vector retrieval and incremental document processing</td><td>Retrieval modes, storage boundaries, and deletion reconstruction</td></tr><tr><td><a href="https://github.com/HKUDS/RAG-Anything" target="_blank" rel="noreferrer">RAG-Anything — HKUDS</a></td><td>Multimodal research framework related to LightRAG</td><td>Structured parsing and cross-modal extraction</td><td>Keep tables, figures, and equations connected to surrounding text</td></tr><tr><td><a href="https://github.com/SciPhi-AI/R2R" target="_blank" rel="noreferrer">R2R — SciPhi</a></td><td>Retrieval application/platform</td><td>Ingestion, hybrid retrieval, graph extraction, document APIs</td><td>Product-level API and collection boundaries</td></tr><tr><td><a href="https://github.com/deepset-ai/haystack" target="_blank" rel="noreferrer">Haystack — deepset</a></td><td>Python component/pipeline framework</td><td>Explicit processing dependencies and retrieval composition</td><td>Typed component inputs, branching, and inspectable pipelines</td></tr><tr><td><a href="https://github.com/run-llama/llama_index" target="_blank" rel="noreferrer">LlamaIndex PropertyGraphIndex</a></td><td>Component within a Python data framework</td><td>Schema-guided graph extraction and combined retrievers</td><td>Separate extractors, graph stores, and retrieval methods</td></tr><tr><td><a href="https://github.com/topoteretes/cognee" target="_blank" rel="noreferrer">Cognee</a></td><td>Self-hosted memory engine/platform</td><td>Document enrichment, provenance, and graph/vector search</td><td>Storage responsibilities and ontology grounding</td></tr><tr><td><a href="https://github.com/getzep/graphiti" target="_blank" rel="noreferrer">Graphiti — Zep</a></td><td>Temporal graph construction/retrieval framework</td><td>Entity resolution, evolving claims, and incremental graphs</td><td>Source episodes, temporal validity, and fact invalidation</td></tr></tbody></table><h2 id="microsoft-graphrag" tabindex="-1">Microsoft GraphRAG <a class="header-anchor" href="#microsoft-graphrag" aria-label="Permalink to &quot;Microsoft GraphRAG&quot;">​</a></h2><p>Study the <a href="https://microsoft.github.io/graphrag/index/default_dataflow/" target="_blank" rel="noreferrer">indexing dataflow</a> for the transition from text units to extracted entities, relationships, communities, reports, and embeddings. The <a href="https://microsoft.github.io/graphrag/query/overview/" target="_blank" rel="noreferrer">query overview</a> distinguishes local retrieval combining graph information with source chunks from global retrieval over community reports.</p><p>This is useful for defining our intermediate artifacts and deciding which summaries deserve their own indexes. Global report-based answering is a separate workload from our ordinary low-latency grounded chat path. The repository currently describes itself as largely in maintenance mode and as a research demonstration, so its methodology is a stronger reason to study it than an assumed future feature roadmap. <a href="https://github.com/microsoft/graphrag#graphrag" target="_blank" rel="noreferrer">Repository status</a></p><h2 id="lightrag" tabindex="-1">LightRAG <a class="header-anchor" href="#lightrag" aria-label="Permalink to &quot;LightRAG&quot;">​</a></h2><p>Read the <a href="https://github.com/HKUDS/LightRAG#selecting-query-modes" target="_blank" rel="noreferrer">query modes</a> and <a href="https://github.com/HKUDS/LightRAG#selecting-backend-storage" target="_blank" rel="noreferrer">storage configuration</a>. Its local, global, naive, hybrid, and mix modes provide useful retrieval ablations. Its use of the word “hybrid” combines local/global retrieval; this should not be assumed to mean our specific BM25-plus-vector fusion.</p><p>Study how document deletion affects derived entities and relationships, and how extraction caches support reconstruction. Its separate key-value, vector, graph, and document-status responsibilities are relevant even if our experiment places them in one SQLite database. Reusing the Python framework or server would be a different deployment decision from implementing a Rust retrieval adapter.</p><h2 id="rag-anything" tabindex="-1">RAG-Anything <a class="header-anchor" href="#rag-anything" aria-label="Permalink to &quot;RAG-Anything&quot;">​</a></h2><p>The <a href="https://github.com/HKUDS/RAG-Anything#core-algorithm" target="_blank" rel="noreferrer">core algorithm</a> describes document parsing, modality-specific analysis, graph construction, and retrieval. This is especially relevant if our documents contain tables, diagrams, or equations whose meaning disappears when flattened into plain text.</p><p>Study how parsed content retains hierarchy and how multimodal elements link to nearby text. We would still attach generated descriptions to exact source locations and distinguish them from source evidence. LightRAG&#39;s current README reports integrated multimodal processing starting with v1.5; treat the standalone RAG-Anything package and integrated LightRAG release as distinct compatibility targets before selecting dependencies. <a href="https://github.com/HKUDS/LightRAG#multimodal-capability-upgrades" target="_blank" rel="noreferrer">Integrated multimodal processing</a></p><h2 id="r2r" tabindex="-1">R2R <a class="header-anchor" href="#r2r" aria-label="Permalink to &quot;R2R&quot;">​</a></h2><p>R2R&#39;s <a href="https://github.com/SciPhi-AI/R2R#using-the-api" target="_blank" rel="noreferrer">API examples</a> and <a href="https://github.com/SciPhi-AI/R2R#key-features" target="_blank" rel="noreferrer">feature overview</a> combine document operations, citation-bearing RAG, semantic/keyword retrieval with rank fusion, and automatic entity/relationship extraction. This makes it a useful application-level comparison, rather than only an extraction library.</p><p>Study which operations the API exposes independently and how document/collection management relates to retrieval. Adopting the complete platform would replace substantial backend responsibilities; our current design keeps those contracts in Rust. The hosted documentation root linked by the repository returned 404 during this check, so the links here use the verified repository README. Validate current deployment instructions before evaluating it as a runnable baseline.</p><h2 id="haystack" tabindex="-1">Haystack <a class="header-anchor" href="#haystack" aria-label="Permalink to &quot;Haystack&quot;">​</a></h2><p>The <a href="https://docs.haystack.deepset.ai/docs/pipelines" target="_blank" rel="noreferrer">pipeline documentation</a> explains components connected as directed multigraphs, including branches, simultaneous flows, and loops. Its component-oriented approach is a useful reference for the contracts between parsing, extraction, retrieval, routing, and generation.</p><p>Our ingestion workflow deliberately uses acyclic dependencies with bounded repair stages. A component execution graph also does not, by itself, establish the durable ownership, revision checks, and crash-recovery guarantees required by our orchestrator. Haystack is worth studying or using inside a Python worker; adopting it for live chat orchestration would change the Rust serving boundary. Keep component execution and workflow durability explicit during comparison.</p><h2 id="llamaindex-propertygraphindex" tabindex="-1">LlamaIndex PropertyGraphIndex <a class="header-anchor" href="#llamaindex-propertygraphindex" aria-label="Permalink to &quot;LlamaIndex PropertyGraphIndex&quot;">​</a></h2><p>The <a href="https://developers.llamaindex.ai/python/framework/module_guides/indexing/lpg_index_guide/" target="_blank" rel="noreferrer">property-graph guide</a> separates graph extraction, storage, and retrieval. Its <code>SchemaLLMPathExtractor</code> validates paths against allowed entity types, relationship types, and permitted connections. It also shows combining several graph retrievers.</p><p>This is a concrete reference for our ontology and extraction-schema design. Test schema-constrained extraction against a more permissive baseline to measure rejected useful claims and invalid accepted claims. Its Python interfaces and graph-store integrations are useful adapter examples; they do not establish compatibility with our proposed SQLite graph representation. Schema-valid triples still need evidence locations, disambiguation decisions, temporal qualifiers, and revision-aware retraction in our model.</p><h2 id="cognee" tabindex="-1">Cognee <a class="header-anchor" href="#cognee" aria-label="Permalink to &quot;Cognee&quot;">​</a></h2><p>Cognee&#39;s <a href="https://docs.cognee.ai/core-concepts/architecture" target="_blank" rel="noreferrer">architecture</a> assigns different responsibilities to relational provenance, vector similarity, and graph relationships. Its <a href="https://docs.cognee.ai/guides/ontology-support" target="_blank" rel="noreferrer">ontology guide</a> shows grounding extracted entities and types to an OWL ontology, including a mode that retains unmatched entities.</p><p>Study this separation of responsibilities and the treatment of unmatched concepts. It is a useful counterpoint to our unified SQLite experiment: co-locating indexes must preserve the same distinctions in data ownership and provenance. Cognee also addresses persistent agent memory across sessions, a broader scope than our initial document-grounded chat system. Its ontology grounding is a specific mechanism to evaluate, rather than automatic proof of correct entity resolution.</p><h2 id="graphiti" tabindex="-1">Graphiti <a class="header-anchor" href="#graphiti" aria-label="Permalink to &quot;Graphiti&quot;">​</a></h2><p>The <a href="https://help.getzep.com/graphiti/getting-started/overview" target="_blank" rel="noreferrer">Graphiti overview</a> explains temporal context graphs, entity/edge extraction, fact invalidation, and hybrid retrieval. The <a href="https://github.com/getzep/graphiti#what-is-a-context-graph" target="_blank" rel="noreferrer">repository&#39;s graph model</a> connects derived facts to source episodes and describes validity windows.</p><p>This is the closest reference for correcting evolving relationships while preserving their history. Study the distinction between when a statement was recorded and when it applies, and how contradictory information affects current retrieval. Graphiti supplies a Python framework around supported graph backends; it is not a drop-in SQLite extension or our SSE gateway. Its published comparative performance claims require independent testing on our corpus and access filters.</p><h2 id="four-projects-to-study-first" tabindex="-1">Four projects to study first <a class="header-anchor" href="#four-projects-to-study-first" aria-label="Permalink to &quot;Four projects to study first&quot;">​</a></h2><ol><li><strong>LightRAG:</strong> build retrieval-mode and deletion-reconstruction experiments for the <a href="/knowledge-lab/architecture/retrieval">retrieval design</a>.</li><li><strong>Graphiti:</strong> refine evidence, temporal validity, and correction rules in the <a href="/knowledge-lab/architecture/contracts">contracts</a>.</li><li><strong>LlamaIndex PropertyGraphIndex:</strong> prototype typed extraction and measure schema adherence plus grounding in the <a href="/knowledge-lab/architecture/ingestion">ingestion pipeline</a>.</li><li><strong>Microsoft GraphRAG:</strong> use its artifact model and local/global split to decide whether community summaries improve our actual questions.</li></ol><p>Any reuse decision should pin a revision, inspect that revision&#39;s license and dependencies, and run a small representative corpus through ingestion, restricted retrieval, update/deletion, and citation checks. These references inform the design; our measured relevance, freshness, and streaming behavior will decide adoption.</p>',32)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
